Ext._define('workflow.vertex.Grid', {
    extend: 'core.RestfulGrid',

    restWindow: 'workflow.vertex.Window',

    configOrderToolBar: ['vertex', '-', 'edit', 'remove', '-', 'search', '->', 'download'],

    singleton: {
        classDB: [],

        register: function(name, label, iconCls, Class) {
            workflow.vertex.Grid.classDB.push({
                name: name,
                label: label,
                iconCls: iconCls,
                Class: Class
            });
        },

        getClassByName: function(name) {
            var Class = false;

            workflow.vertex.Grid.classDB.forEach(
                function(item) {
                    if(item.name == name) {
                        Class = item.Class;
                        return false;
                    }
                }
            );

            return Class;
        },

        getNewMenu: function(scope) {
            if(workflow.vertex.Grid.classDB.length > 0) {
                return workflow.vertex.Grid.classDB.map(
                    function(item) {
                        return {
                            text: item.label,
                            scope: scope,
                            iconCls: item.iconCls,
                            handler: function() {
                                this.createItem(item.Class);
                            }
                        };
                    }
                );
            }
            else
                return [
                    {
                        text: 'Nenhum tipo foi especificado',
                        enable: false
                    }
                ];
        }
    },

    createItem: function(classDef) {
        Ext._create(
            classDef,
            {
                action: 'create',
                params: this.getParams(),
                values: {},
                callback: {
                    success: {
                        scope: this,
                        fn: function() {
                            this.getStore().reload();
                        }
                    }
                }
            }
        ).show();
    },

    updateItem: function(record) {
        if(record instanceof Ext.Button)
            record = undefined;

        var selected = core.nullValue(record, this.getSelectionModel().getSelected());

        if(selected) {
            var Class = workflow.vertex.Grid.getClassByName(selected.get('kind'));
            Ext._create(Class, {
                action: 'update',
                oId: selected.get('pk'),
                values: 'remote',
                params: this.getParams(),
                callback: {
                    success: {
                        scope: this,
                        fn: function() {
                            this.getStore().reload();
                        }
                    }
                }
            }).show();
        }
        else
            Ext.Msg.show({
                title: 'Editando',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK,
                msg: 'Primeiro selecione um item para editar.'
            });
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: '', dataIndex: 'icons', width: 30, renderer: core.rendererIconGrid},
                    {header: 'Nome', dataIndex: 'name', id: 'autoExpandColumn'},
                    {header: 'Acrônimo', dataIndex: 'acronym', width: 140},
                    {header: 'Tipo', dataIndex: 'kind', width: 140, hidden: true},
                    {header: 'Alvo', dataIndex: 'objective', width: 90, hidden: true},
                    {header: 'Ativo', dataIndex: 'active', width: 45, renderer: function(value) { return (value ? 'Sim' : 'Não'); }},
                    {header: 'Início', dataIndex: 'beginning', width: 45, renderer: function(value) { return (value ? 'Sim' : 'Não'); }},
                    {header: 'Descrição', dataIndex: 'description', width: 180, hidden: true}
                ]
            );

        return this._columnModel;
    },

    getVertexAction: function(cfg) {
        if(!this._createVertex)
            this._createVertex = Ext._create('Ext.Button', {
                text: 'Novo',
                iconCls: 'icon-core icon-core-add',
                menu: workflow.vertex.Grid.getNewMenu(this)
            });

        return this._createVertex;
    }

});

core.RestfulGrid.register(
    'workflow.vertex.Restful',
    'workflow.vertex.Grid'
);
